<!--
 * 任务分片管理（列表页）
 *
 * @path apps\cronjob-web\src\views\job-task\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 任务分片管理（P1-MapReduce 分片可视化）
 * <p>消费后端契约 jobTask.ts（auto-generated by bash/gen-contract.py）：
 * list 分片列表、page 分片分页、progress 分片进度。
 * 布局：顶部筛选栏（执行日志 ID）+ 分片分页列表 + 进度概览卡片 + 详情抽屉。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page } from '@ydsz/common-ui';

import { Badge, Button, Sheet, SheetContent, SheetHeader, SheetTitle } from '@ydsz-core/ui-kit/shadcn-ui';
// TODO: ElDescriptions/ElDescriptionsItem/ElProgress 暂无 shadcn 对应;保留 element-plus SKIP
import { ElDescriptions, ElDescriptionsItem, ElProgress } from 'element-plus';
import { computed, onMounted, ref } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { list, page, progress } from '#/api/jobTask';
import type { JobTaskVO } from '#/api/models';

import { createLogger } from '@ydsz-core/shared/utils';

const logger = createLogger('cronjob-job-task');

defineOptions({ name: 'JobTaskManagement' });

// ==================== 数据 ====================

/** 当前过滤的执行日志 ID */
const currentLogId = ref<string>('');
/** 分片全量数据（progress API 返回） */
const progressData = ref<Record<string, Record<string, unknown>>>({});

// ==================== 进度概览 ====================

/** 计算进度百分比 */
const progressPercent = computed(() => {
  const statuses = Object.values(progressData.value);
  if (statuses.length === 0) return 0;
  const done = statuses.filter((s) => s?.status === 'SUCCESS' || s?.status === 'FAILED').length;
  return Math.round((done / statuses.length) * 100);
});

/** 成功分片数 */
const successCount = computed(() => {
  return Object.values(progressData.value).filter((s) => s?.status === 'SUCCESS').length;
});

/** 失败分片数 */
const failCount = computed(() => {
  return Object.values(progressData.value).filter((s) => s?.status === 'FAILED').length;
});

/** 运行中分片数 */
const runningCount = computed(() => {
  return Object.values(progressData.value).filter((s) => s?.status === 'RUNNING').length;
});

// ==================== 详情抽屉 ====================

/** 详情抽屉可见性 */
const isDetailVisible = ref(false);
/** 当前查看的分片 */
const detailRecord = ref<JobTaskVO | null>(null);

/** 打开详情抽屉 */
function handleViewDetail(row: JobTaskVO): void {
  detailRecord.value = row;
  isDetailVisible.value = true;
}

// ==================== 工具方法 =================---

/** 判断是否为 ROOT 类型 */
function isRoot(row: JobTaskVO): boolean {
  return row.taskType === 'ROOT';
}

/** 判断是否为 SUCCESS 状态 */
function isSuccess(row: JobTaskVO): boolean {
  return row.taskStatus === 'SUCCESS' || row.taskStatus === '0';
}

/** 判断是否为 FAILED 状态 */
function isFailed(row: JobTaskVO): boolean {
  return row.taskStatus === 'FAILED';
}

/** 判断是否为 RUNNING 状态 */
function isRunning(row: JobTaskVO): boolean {
  return row.taskStatus === 'RUNNING';
}

/** 任务状态中文映射 */
function translateTaskStatus(status?: string): string {
  const map: Record<string, string> = {
    PENDING: '待执行',
    RUNNING: '执行中',
    SUCCESS: '成功',
    FAILED: '失败',
  };
  return map[status ?? ''] ?? status ?? '-';
}

/** 任务状态标签颜色 */
function taskStatusTagType(row: JobTaskVO): 'primary' | 'success' | 'danger' | 'warning' {
  if (isSuccess(row)) return 'success';
  if (isFailed(row)) return 'danger';
  if (isRunning(row)) return 'warning';
  return 'primary';
}

// ==================== 数据加载 ====================

/** 加载进度数据 */
async function loadProgress(logId?: string): Promise<void> {
  if (!logId) {
    progressData.value = {};
    return;
  }
  try {
    const result = await progress({ logId });
    progressData.value = result ?? {};
  } catch {
    logger.warn('加载分片进度失败', logId);
    progressData.value = {};
  }
}

// ==================== Vxe 表格 ====================

const gridOptions: VxeTableGridOptions<JobTaskVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'taskName', title: '分片名称', width: 140 },
    {
      field: 'taskType',
      title: '类型',
      width: 90,
      slots: {
        default: ({ row }) => {
          const item = row as JobTaskVO;
          return h(
            Badge,
            { size: 'sm', variant: isRoot(item) ? 'default' : 'secondary' },
            () => (isRoot(item) ? '根任务' : '子任务'),
          );
        },
      },
    },
    { field: 'jobKey', title: '任务标识', width: 140 },
    {
      field: 'taskStatus',
      title: '状态',
      width: 100,
      slots: {
        default: ({ row }) => {
          const item = row as JobTaskVO;
          return h(Badge, { variant: taskStatusTagType(item), size: 'sm' }, () =>
            translateTaskStatus(item.taskStatus),
          );
        },
      },
    },
    { field: 'execNodeId', title: '执行节点', width: 140 },
    { field: 'retryCount', title: '重试次数', width: 90 },
    { field: 'createdAt', title: '创建时间', width: 170 },
    {
      field: 'action',
      title: '操作',
      width: 80,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const item = row as JobTaskVO;
          return h(
            Button,
            { size: 'sm', variant: 'link', onClick: () => handleViewDetail(item) },
            () => '详情',
          );
        },
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async ({ page: pageInfo }, formValues) => {
        const logId = (formValues?.logId as string) || currentLogId.value || undefined;
        currentLogId.value = logId ?? '';
        // 同步加载进度数据
        await loadProgress(logId);
        const res = await page({
          logId,
          page: pageInfo.currentPage,
          size: pageInfo.pageSize,
        });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'logId',
        title: '日志 ID',
        itemRender: { name: 'Input', props: { placeholder: '执行日志 ID' } },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

onMounted(() => {
  // 初始查询（不传 logId 则返回空）
});
</script>

<template>
  <Page auto-content-height>
    <!-- 进度概览卡片 -->
    <div class="mb-3 grid grid-cols-2 gap-3 md:grid-cols-4">
      <ElCard shadow="never">
        <div class="text-xs text-gray-500">总分片数</div>
        <div class="text-xl font-semibold text-blue-500">
          {{ Object.keys(progressData).length || 0 }}
        </div>
      </ElCard>
      <ElCard shadow="never">
        <div class="text-xs text-gray-500">成功</div>
        <div class="text-xl font-semibold text-green-500">{{ successCount }}</div>
      </ElCard>
      <ElCard shadow="never">
        <div class="text-xs text-gray-500">失败</div>
        <div class="text-xl font-semibold text-red-500">{{ failCount }}</div>
      </ElCard>
      <ElCard shadow="never">
        <div class="text-xs text-gray-500">执行中</div>
        <div class="text-xl font-semibold text-orange-500">{{ runningCount }}</div>
      </ElCard>
    </div>

    <!-- 总体进度 -->
    <ElCard v-if="Object.keys(progressData).length > 0" shadow="never" class="mb-3">
      <template #header>
        <span class="font-medium">分片执行进度</span>
      </template>
      <ElProgress
        :percentage="progressPercent"
        :stroke-width="16"
        :text-inside="true"
        :status="progressPercent === 100 ? 'success' : ''"
      />
    </ElCard>

    <Grid table-title="任务分片管理" />

    <!-- 详情 Sheet -->
    <Sheet v-model:open="isDetailVisible">
      <SheetContent side="right" class="w-[600px]">
        <SheetHeader>
          <SheetTitle>任务分片详情</SheetTitle>
        </SheetHeader>
      <template v-if="detailRecord">
        <ElDescriptions :column="2" border size="small">
          <ElDescriptionsItem label="分片名称">{{ detailRecord.taskName ?? '-' }}</ElDescriptionsItem>
          <ElDescriptionsItem label="类型">
            <Badge size="sm" :variant="isRoot(detailRecord) ? 'default' : 'secondary'">
              {{ isRoot(detailRecord) ? '根任务' : '子任务' }}
            </Badge>
          </ElDescriptionsItem>
          <ElDescriptionsItem label="任务标识">{{ detailRecord.jobKey ?? '-' }}</ElDescriptionsItem>
          <ElDescriptionsItem label="状态">
            <Badge size="sm" :variant="taskStatusTagType(detailRecord)">
              {{ translateTaskStatus(detailRecord.taskStatus) }}
            </Badge>
          </ElDescriptionsItem>
          <ElDescriptionsItem label="执行节点">{{ detailRecord.execNodeId ?? '-' }}</ElDescriptionsItem>
          <ElDescriptionsItem label="重试次数">{{ detailRecord.retryCount ?? 0 }}</ElDescriptionsItem>
          <ElDescriptionsItem label="创建时间">{{ detailRecord.createdAt ?? '-' }}</ElDescriptionsItem>
          <ElDescriptionsItem label="更新时间">{{ detailRecord.updatedAt ?? '-' }}</ElDescriptionsItem>
          <ElDescriptionsItem v-if="detailRecord.taskParams" label="任务参数" :span="2">
            <pre class="max-h-32 overflow-auto whitespace-pre-wrap break-all text-xs">{{ detailRecord.taskParams }}</pre>
          </ElDescriptionsItem>
          <ElDescriptionsItem v-if="detailRecord.result" label="执行结果" :span="2">
            <pre class="max-h-32 overflow-auto whitespace-pre-wrap break-all text-xs">{{ detailRecord.result }}</pre>
          </ElDescriptionsItem>
          <ElDescriptionsItem v-if="detailRecord.errorMessage" label="错误信息" :span="2">
            <pre class="max-h-32 overflow-auto whitespace-pre-wrap break-all text-xs text-red-500">{{ detailRecord.errorMessage }}</pre>
          </ElDescriptionsItem>
        </ElDescriptions>
      </template>
      </SheetContent>
    </Sheet>
  </Page>
</template>
